    TwistExpander_Antares_Arx::KDF_B_A_A(PARAMS_KDF);

    //
    // src: [$evocation]
    // dst: [$runic]
    //
    TwistExpander_Antares_Arx::KDF_B_B_A(PARAMS_KDF);

    //
    // ent: [$evocation]
    // src: [$runic]
    // dst: [$divination]
